-- PostgreSQL. The tables of document_totals.sql in an empty database (live_totals_run.py pg creates them again on every run):
-- psql -h localhost -U <login> -d <database> -v ON_ERROR_STOP=1 -f document_totals_postgres.sql
DROP TABLE IF EXISTS "InvoiceAllowanceCharge";
DROP TABLE IF EXISTS "InvoiceLine";
DROP TABLE IF EXISTS "TaxCategory";
DROP TABLE IF EXISTS "Invoice";
CREATE TABLE "Invoice" (
    "InvoiceId" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "Customer" varchar(60) NOT NULL,
    "InvoiceDate" date NOT NULL DEFAULT '2024-06-01',
    "Currency" varchar(3) NOT NULL DEFAULT 'USD',
    "ItemsTotal" numeric(18, 2) NOT NULL DEFAULT 0,
    "AllowanceTotal" numeric(18, 2) NOT NULL DEFAULT 0,
    "ChargeTotal" numeric(18, 2) NOT NULL DEFAULT 0,
    "TaxExclusive" numeric(18, 2) NOT NULL DEFAULT 0,
    "TaxTotal" numeric(18, 2) NOT NULL DEFAULT 0,
    "TaxInclusive" numeric(18, 2) NOT NULL DEFAULT 0,
    "Prepaid" numeric(18, 2) NOT NULL DEFAULT 0,
    "Rounding" numeric(18, 2) NOT NULL DEFAULT 0,
    "Payable" numeric(18, 2) NOT NULL DEFAULT 0
);
CREATE TABLE "TaxCategory" (
    "TaxCategoryId" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "Code" varchar(10) NOT NULL,
    "Name" varchar(60) NOT NULL,
    "Rate" numeric(9, 4) NOT NULL,
    "ExemptionReason" varchar(200) NULL,
    "ValidFrom" date NOT NULL DEFAULT '2000-01-01',
    "ValidTo" date NULL
);
CREATE UNIQUE INDEX "UX_TaxCategory_Code" ON "TaxCategory" ("Code");
CREATE TABLE "InvoiceLine" (
    "InvoiceLineId" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "InvoiceId" integer NOT NULL REFERENCES "Invoice" ("InvoiceId"),
    "LineDate" date NOT NULL DEFAULT '2024-06-01',
    "Description" varchar(100) NOT NULL,
    "TaxCategoryId" integer NULL REFERENCES "TaxCategory" ("TaxCategoryId"),
    "TaxRate" numeric(9, 4) NOT NULL DEFAULT 0,
    "LineTotal" numeric(18, 2) NOT NULL,
    "TaxAmount" numeric(18, 2) NOT NULL DEFAULT 0
);
CREATE TABLE "InvoiceAllowanceCharge" (
    "InvoiceAllowanceChargeId" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "InvoiceId" integer NOT NULL REFERENCES "Invoice" ("InvoiceId"),
    "IsCharge" boolean NOT NULL,
    "ReasonCode" varchar(10) NULL,
    "BaseAmount" numeric(18, 2) NULL,
    "Percentage" numeric(9, 4) NULL,
    "Amount" numeric(18, 2) NOT NULL
);
